	ident, ok := expr.(*ast.Ident)
	if !ok {
		return nil
	}

	var lastCall *ast.CallExpr

	ast.Inspect(body, func(n ast.Node) bool {
		if n == nil || n.Pos() >= ret.Pos() {
			return false
		}

		switch stmt := n.(type) {
		case *ast.AssignStmt:
			for i, lhs := range stmt.Lhs {
				if id, isId := lhs.(*ast.Ident); isId && id.Name == ident.Name {
					var rhs ast.Expr
					if len(stmt.Rhs) == 1 {
						rhs = stmt.Rhs[0]
					} else if i < len(stmt.Rhs) {
