						for i, name := range valueSpec.Names {
							if name.Name == ident.Name {
								var rhs ast.Expr
								if i < len(valueSpec.Values) {
									rhs = valueSpec.Values[i]
								}
								if rhsCall, isCall := rhs.(*ast.CallExpr); isCall {
