	}

	if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
		if selection := pass.TypesInfo.Selections[sel]; selection != nil && selection.Kind() == types.MethodVal {
			recv := selection.Recv()
			if isInterface(recv) {
