					if fnObj.Pkg() != nil && isPackageIgnored(cfg.IgnorePackageGlobs, fnObj.Pkg().Path()) {
						return
					}
					pass.Reportf(expr.Pos(), "error returned from interface method should be wrapped: sig: %s", sig)
					return
				}
			}
		}
	}

	pkg := fnObj.Pkg()
	if pkg == nil {
		return
	}

	pkgPath := pkg.Path()

	if isPackageIgnored(cfg.IgnorePackageGlobs, pkgPath) {
		return
	}

	isInternal := (pkgPath == pass.Pkg.Path())

	if !isInternal {
		pass.Reportf(expr.Pos(), "error returned from external package is unwrapped: sig: %s", sig)
		return
	}

	if cfg.ReportInternalErrors {
		pass.Reportf(expr.Pos(), "package-internal error should be wrapped: sig: %s", sig)
		return
	}
}

func getCalledFuncObj(pass *analysis.Pass, call *ast.CallExpr) types.Object {
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		return pass.TypesInfo.ObjectOf(fun)
	case *ast.SelectorExpr:
		if selection := pass.TypesInfo.Selections[fun]; selection != nil {
			return selection.Obj()
		}
		return pass.TypesInfo.ObjectOf(fun.Sel)
	}
	return nil
}

func isInterface(t types.Type) bool {
	if t == nil {
		return false
	}
	if types.IsInterface(t) {
		return true
	}
	_, ok := t.Underlying().(*types.Interface)
	return ok
}

func isPackageIgnored(globs []string, pkgPath string) bool {
	for _, pattern := range globs {
		if matchGlob(pattern, pkgPath) {
			return true
		}
	}
	return false
}

func matchGlob(pattern, name string) bool {
	if matched, _ := filepath.Match(pattern, name); matched {
		return true
	}
	if matched, _ := path.Match(pattern, name); matched {
		return true
	}
	if strings.HasSuffix(pattern, "/*") {
		prefix := strings.TrimSuffix(pattern, "/*")
		if strings.HasPrefix(name, prefix+"/") || name == prefix {
			return true
		}
	}
	if strings.HasSuffix(pattern, "/**") {
		prefix := strings.TrimSuffix(pattern, "/**")
		if strings.HasPrefix(name, prefix+"/") || name == prefix {
			return true
		}
	}
	return false
}
EOF

