{"command":"cat <<'EOF' > /workspace/wrapcheck.go
package wrapcheck

import (
	"go/ast"
	"go/types"
	"log"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"strings"

	"golang.org/x/tools/go/analysis"
	"gopkg.in/yaml.v3"
)

var defaultIgnoreSigs = []string{
	".Errorf(",
	"errors.New(",
	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

type Config struct {
	IgnoreSigs             []string `yaml:"ignoreSigs"`
	ExtraIgnoreSigs        []string `yaml:"extraIgnoreSigs"`
	IgnoreSigRegexps       []string `yaml:"ignoreSigRegexps"`
	IgnorePackageGlobs     []string `yaml:"ignorePackageGlobs"`
	IgnoreInterfaceRegexps []string `yaml:"ignoreInterfaceRegexps"`
	ReportInternalErrors   bool     `yaml:"reportInternalErrors"`
}

func NewAnalyzer() *analysis.Analyzer {
	return &analysis.Analyzer{
		Name: "wrapcheck",
		Doc:  "Checks that errors returned from external packages are wrapped",
		Run:  run,
	}
}

var Analyzer = NewAnalyzer()

var errInit = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

func isError(t types.Type) bool {
	if t == nil {
		return false
	}
	return types.Implements(t, errInit) || types.AssertableTo(errInit, t)
}

func loadConfig() Config {
	cfg := Config{}

	dirs := []string{"."}
	if home, hErr := os.UserHomeDir(); hErr == nil && home != "" {
		dirs = append(dirs, home)
	}

	foundPath := ""
	for _, dir := range dirs {
		for _, name := range []string{".wrapcheck.yaml", ".wrapcheck.yml"} {
			p := filepath.Join(dir, name)
			if _, statErr := os.Stat(p); statErr == nil {
				foundPath = p
				break
			}
		}
		if foundPath != "" {
			break
		}
	}

	if foundPath == "" {
		cfg.IgnoreSigs = defaultIgnoreSigs
		return cfg
	}

	configData, err := os.ReadFile(foundPath)
	if err != nil {
		log.Fatalf("failed to parse config: While parsing config: %v", err)
	}

	var rawMap map[string]interface{}
	if err := yaml.Unmarshal(configData, &rawMap); err != nil {
		log.Fatalf("failed to parse config: While parsing config: %v", err)
	}

	if err := yaml.Unmarshal(configData, &cfg); err != nil {
		log.Fatalf("failed to parse config: While parsing config: %v", err)
	}

	if rawMap != nil {
		if _, ok := rawMap["ignoreSigs"]; !ok {
			cfg.IgnoreSigs = defaultIgnoreSigs
		}
	} else {
		cfg.IgnoreSigs = defaultIgnoreSigs
	}

	return cfg
}

func run(pass *analysis.Pass) (interface{}, error) {
	cfg := loadConfig()

	ignoreSigs := append(cfg.IgnoreSigs, cfg.ExtraIgnoreSigs...)

	var ignoreSigRes []*regexp.Regexp
	for _, pattern := range cfg.IgnoreSigRegexps {
		re, err := regexp.Compile(pattern)
		if err == nil {
			ignoreSigRes = append(ignoreSigRes, re)
		}
	}

	var ignoreIfaceRes []*regexp.Regexp
	for _, pattern := range cfg.IgnoreInterfaceRegexps {
		re, err := regexp.Compile(pattern)
		if err == nil {
			ignoreIfaceRes = append(ignoreIfaceRes, re)
		}
	}

	for _, file := range pass.Files {
		ast.Inspect(file, func(n ast.Node) bool {
			fnDecl, ok := n.(*ast.FuncDecl)
			if !ok {
				fnLit, isLit := n.(*ast.FuncLit)
				if !isLit {
					return true
				}
				inspectBody(pass, cfg, ignoreSigs, ignoreSigRes, ignoreIfaceRes, fnLit.Body)
				return true
			}
			inspectBody(pass, cfg, ignoreSigs, ignoreSigRes, ignoreIfaceRes, fnDecl.Body)
			return true
		})
	}

	return nil, nil
}

func inspectBody(pass *analysis.Pass, cfg Config, ignoreSigs []string, ignoreSigRes, ignoreIfaceRes []*regexp.Regexp, body *ast.BlockStmt) {
	if body == nil {
		return
	}

	ast.Inspect(body, func(n ast.Node) bool {
		if _, isLit := n.(*ast.FuncLit); isLit && n != body {
			return false
		}

		ret, ok := n.(*ast.ReturnStmt)
		if !ok || len(ret.Results) == 0 {
			return true
		}

		for _, expr := range ret.Results {
			exprType := pass.TypesInfo.TypeOf(expr)
			if exprType == nil {
				continue
			}

			if tuple, isTuple := exprType.(*types.Tuple); isTuple {
				for i := 0; i < tuple.Len(); i++ {
					if isError(tuple.At(i).Type()) {
						checkExpr(pass, cfg, ignoreSigs, ignoreSigRes, ignoreIfaceRes, body, ret, expr)
						break
					}
				}
			} else if isError(exprType) {
				checkExpr(pass, cfg, ignoreSigs, ignoreSigRes, ignoreIfaceRes, body, ret, expr)
			}
		}

		return true
	})
}

func findCall(body *ast.BlockStmt, ret *ast.ReturnStmt, expr ast.Expr) *ast.CallExpr {
	if call, ok := expr.(*ast.CallExpr); ok {
		return call
	}

	ident, ok := expr.(*ast.Ident)
	if !ok {
		return nil
	}

	var lastCall *ast.CallExpr

	ast.Inspect(body, func(n ast.Node) bool {
		if n == nil || n.Pos() >= ret.Pos() {
			return false
		}

		switch stmt := n.(type) {
		case *ast.AssignStmt:
			for i, lhs := range stmt.Lhs {
				if id, isId := lhs.(*ast.Ident); isId && id.Name == ident.Name {
					var rhs ast.Expr
					if len(stmt.Rhs) == 1 {
						rhs = stmt.Rhs[0]
					} else if i < len(stmt.Rhs) {
						rhs = stmt.Rhs[i]
					}

					if rhsCall, isCall := rhs.(*ast.CallExpr); isCall {
						lastCall = rhsCall
					} else {
						lastCall = nil
					}
				}
			}
		case *ast.DeclStmt:
			if genDecl, isGen := stmt.Decl.(*ast.GenDecl); isGen {
				for _, spec := range genDecl.Specs {
					if valueSpec, isVal := spec.(*ast.ValueSpec); isVal {
						for i, name := range valueSpec.Names {
							if name.Name == ident.Name {
								var rhs ast.Expr
								if i < len(valueSpec.Values) {
									rhs = valueSpec.Values[i]
								}
								if rhsCall, isCall := rhs.(*ast.CallExpr); isCall {
									lastCall = rhsCall
								} else {
									lastCall = nil
								}
							}
						}
					}
				}
			}
		}

		return true
	})

	return lastCall
}

func checkExpr(pass *analysis.Pass, cfg Config, ignoreSigs []string, ignoreSigRes, ignoreIfaceRes []*regexp.Regexp, body *ast.BlockStmt, ret *ast.ReturnStmt, expr ast.Expr) {
	call := findCall(body, ret, expr)
	if call == nil {
		return
	}

	fnObj := getCalledFuncObj(pass, call)
	if fnObj == nil {
		return
	}

	sig := fnObj.String()

	for _, s := range ignoreSigs {
		if strings.Contains(sig, s) {
			return
		}
	}

	for _, re := range ignoreSigRes {
		if re.MatchString(sig) {
			return
		}
	}

	if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
		if selection := pass.TypesInfo.Selections[sel]; selection != nil && selection.Kind() == types.MethodVal {
			recv := selection.Recv()
			if isInterface(recv) {
				ifaceStr := recv.String()

				matchedIface := false
				for _, re := range ignoreIfaceRes {
					if re.MatchString(ifaceStr) {
						matchedIface = true
						break
					}
				}

				if !matchedIface {
					if fnObj.Pkg() != nil && isPackageIgnored(cfg.IgnorePackageGlobs, fnObj.Pkg().Path()) {
						return
					}
					pass.Reportf(expr.Pos(), "error returned from interface method should be wrapped: sig: %s", sig)
					return
				}
			}
		}
	}

	pkg := fnObj.Pkg()
	if pkg == nil {
		return
	}

	pkgPath := pkg.Path()

	if isPackageIgnored(cfg.IgnorePackageGlobs, pkgPath) {
		return
	}

	isInternal := (pkgPath == pass.Pkg.Path())

	if !isInternal {
		pass.Reportf(expr.Pos(), "error returned from external package is unwrapped: sig: %s", sig)
		return
	}

	if cfg.ReportInternalErrors {
		pass.Reportf(expr.Pos(), "package-internal error should be wrapped: sig: %s", sig)
		return
	}
}

func getCalledFuncObj(pass *analysis.Pass, call *ast.CallExpr) types.Object {
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		return pass.TypesInfo.ObjectOf(fun)
	case *ast.SelectorExpr:
		if selection := pass.TypesInfo.Selections[fun]; selection != nil {
			return selection.Obj()
		}
		return pass.TypesInfo.ObjectOf(fun.Sel)
	}
	return nil
}

func isInterface(t types.Type) bool {
	if t == nil {
		return false
	}
	if types.IsInterface(t) {
		return true
	}
	_, ok := t.Underlying().(*types.Interface)
	return ok
}

func isPackageIgnored(globs []string, pkgPath string) bool {
	for _, pattern := range globs {
		if matchGlob(pattern, pkgPath) {
			return true
		}
	}
	return false
}

func matchGlob(pattern, name string) bool {
	if matched, _ := filepath.Match(pattern, name); matched {
		return true
	}
	if matched, _ := path.Match(pattern, name); matched {
		return true
	}
	if strings.HasSuffix(pattern, "/*") {
		prefix := strings.TrimSuffix(pattern, "/*")
		if strings.HasPrefix(name, prefix+"/") || name == prefix {
			return true
		}
	}
	if strings.HasSuffix(pattern, "/**") {
		prefix := strings.TrimSuffix(pattern, "/**")
		if strings.HasPrefix(name, prefix+"/") || name == prefix {
			return true
		}
	}
	return false
}
